def test_format_header(self):
    mt = hl.import_vcf(resource('sample2.vcf'))
    metadata = hl.get_vcf_metadata(resource('sample2.vcf'))
    f = new_temp_file(extension='vcf')
    hl.export_vcf(mt, f, metadata=metadata)
    s = set()
    with hl.current_backend().fs.open(f, 'r') as i:
        for line in i:
            if line.startswith('##FORMAT'):
                s.add(line.strip())
    assert s == {'##FORMAT=<ID=GT,Number=1,Type=String,Description="Genotype">', '##FORMAT=<ID=AD,Number=R,Type=Integer,Description="Allelic depths for the ref and alt alleles in the order listed">', '##FORMAT=<ID=DP,Number=1,Type=Integer,Description="Read Depth">', '##FORMAT=<ID=GQ,Number=1,Type=Integer,Description="Genotype Quality">', '##FORMAT=<ID=PL,Number=G,Type=Integer,Description="Normalized, Phred-scaled likelihoods for genotypes as defined in the VCF specification">'}

def test_format_genotypes(self):
    mt = hl.import_vcf(resource('sample.vcf'))
    f = new_temp_file(extension='vcf')
    hl.export_vcf(mt, f)
    with hl.current_backend().fs.open(f, 'r') as i:
        for line in i:
            if line.startswith('20\t13029920'):
                expected = 'GT:AD:DP:GQ:PL\t1/1:0,6:6:18:234,18,0\t1/1:0,4:4:12:159,12,0\t1/1:0,4:4:12:163,12,0\t1/1:0,12:12:36:479,36,0\t1/1:0,4:4:12:149,12,0\t1/1:0,6:6:18:232,18,0\t1/1:0,6:6:18:242,18,0\t1/1:0,3:3:9:119,9,0\t1/1:0,9:9:27:374,27,0\t./.:1,0:1\t1/1:0,3:3:9:133,9,0'
                assert expected in line
                break
        else:
            assert False, 'expected pattern not found'

def test_contigs_header(self):
    mt = hl.import_vcf(resource('sample.vcf')).filter_cols(False)
    f = new_temp_file(extension='vcf')
    hl.export_vcf(mt, f)
    with hl.current_backend().fs.open(f, 'r') as i:
        for line in i:
            if line.startswith('##contig=<ID=10'):
                assert line.strip() == '##contig=<ID=10,length=135534747,assembly=GRCh37>'
                break
        else:
            assert False, 'expected pattern not found'
